#!/usr/bin/env python3
"""Generate native and embedded design tokens. Edit tokens.json, never the generated files."""
import json,pathlib,sys
ROOT=pathlib.Path(__file__).resolve().parents[1]

def outputs():
    data=json.loads((ROOT/'src/Meili.Shared/DesignSystem/tokens.json').read_text())
    def argb(v):return '0x'+('FF'+v[1:] if len(v)==7 else v[1:])
    code='// Generated by build/generate-design-system.py; edit DesignSystem/tokens.json.\nnamespace Meili.Shared.Services;\n\npublic static class DesignTokens\n{\n'
    for name,palette in data['themes'].items():
        code+='    public static readonly ThemePalette '+name.title()+' = new(\n        '+',\n        '.join(k+': '+(str(v) if isinstance(v,int) else argb(v)) for k,v in palette.items())+');\n'
    for key,value in data['metrics'].items():code+=f'    public const double {key} = {value};\n'
    code+='    public static IEnumerable<(string Key,uint Argb)> ComponentBrushes(bool dark) => dark ? DarkBrushes : LightBrushes;\n'
    aliases={'Brand':'BrandBrush','BrandHover':'BrandHoverBrush','Focus':'FocusBrush','Link':'LinkBrush','Input':'InputBackgroundBrush','Hover':'HoverBrush','Pressed':'PressedBrush','Danger':'DangerBrush','Overlay':'OverlayBrush'}
    aliases.update({'Focus':'FocusBrush','Danger':'DangerBrush'})
    for name,colors in data['components'].items():
        code+='    private static readonly (string Key,uint Argb)[] '+name.title()+'Brushes =\n    [\n'+''.join(f'        ("{aliases[k]}", {argb(v)}),\n' for k,v in colors.items())+f'        ("TextControlBorderBrushFocused", {argb(colors["Focus"])}),\n        ("SystemControlErrorTextForegroundBrush", {argb(colors["Danger"])}),\n'+'    ];\n'
    code+='}\n'
    result={'src/Meili.Shared/Services/DesignTokens.cs':code}
    for platform in ['App','Mac']:
        mac=platform=='Mac';ns='https://github.com/avaloniaui' if mac else 'http://schemas.microsoft.com/winfx/2006/xaml/presentation'
        x='<ResourceDictionary xmlns="'+ns+'" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"'+(' xmlns:sys="clr-namespace:System;assembly=System.Runtime"' if mac else ' xmlns:sys="clr-namespace:System;assembly=mscorlib"')+'>\n    <!-- Generated design metrics and typography. -->\n'
        for k,v in data['metrics'].items():
            tag='x:Double' if mac else 'sys:Double';x+=f'    <{tag} x:Key="{k}">{v}</{tag}>\n'
        for key in ['Fast','Standard','Enter']:
            x+=f'    <sys:TimeSpan x:Key="Motion{key}Duration">0:0:0.{data["metrics"]["Motion"+key+"Ms"]:03d}</sys:TimeSpan>\n'
        for key in ['Control','Card','Modal']:
            x+=f'    <CornerRadius x:Key="{key}CornerRadius">{data["metrics"][key+"Radius"]}</CornerRadius>\n'
        for key,family in [('AppFont','Source Sans 3'),('NumberFont','Source Sans 3'),('HeadingFont','Source Serif 4'),('CodeFont','Source Code Pro')]:
            uri=('avares://MeiliMac/Assets/Fonts#' if mac else 'pack://application:,,,/MeiliTerminal;component/Assets/Fonts/#')+family
            fallback=(', PingFang SC, Noto Sans CJK SC, Arial' if mac else ', Microsoft YaHei UI, Segoe UI')
            official='Anthropic Serif' if key=='HeadingFont' else 'Anthropic Mono' if key=='CodeFont' else 'Anthropic Sans'
            x+=f'    <FontFamily x:Key="{key}">{uri}{fallback}</FontFamily>\n'
        x+='</ResourceDictionary>\n';result['src/Meili.'+platform+'/DesignSystem/Tokens.'+('axaml' if mac else 'xaml')]=x
    brush_roles={'ApplicationBackgroundBrush':'Window','SidebarBackgroundBrush':'Sidebar','CardBackgroundFillColorDefaultBrush':'Card','SolidBackgroundFillColorBaseBrush':'Window','SolidBackgroundFillColorSecondaryBrush':'Card','LayerFillColorDefaultBrush':'Window','ControlFillColorDefaultBrush':'Control','ControlFillColorSecondaryBrush':'Control','ControlStrokeColorDefaultBrush':'Border','CardStrokeColorDefaultBrush':'Border','TextFillColorPrimaryBrush':'PrimaryText','TextFillColorSecondaryBrush':'SecondaryText','TextFillColorTertiaryBrush':'MutedText','AccentFillColorDefaultBrush':'Accent','TextOnAccentFillColorPrimaryBrush':'OnAccent','ErrorBarBrush':'ErrorBar','InfoBarBrush':'InfoBar','StaleBadgeBrush':'Badge','BadgeTextBrush':'BadgeText'}
    first='<ResourceDictionary xmlns="https://github.com/avaloniaui" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"><ResourceDictionary.ThemeDictionaries>\n'
    for name,palette in data['themes'].items():
        first+=f'<ResourceDictionary x:Key="{name.title()}">\n'
        for key,role in brush_roles.items():first+=f'<SolidColorBrush x:Key="{key}" Color="{palette[role]}"/>\n'
        for role,color in data['components'][name].items():first+=f'<SolidColorBrush x:Key="{role if role!="Input" else "InputBackground"}Brush" Color="{color}"/>\n'
        first+='</ResourceDictionary>\n'
    first+='</ResourceDictionary.ThemeDictionaries></ResourceDictionary>\n'
    result['src/Meili.Mac/DesignSystem/ThemeDefaults.axaml']=first
    css='/* Generated design metrics and bundled OFL typography. */\n'
    for family,file,weight in [('Source Sans 3','SourceSans3-Regular.ttf',400),('Source Sans 3','SourceSans3-Semibold.ttf',600),('Source Serif 4','SourceSerif4-Regular.ttf',400),('Source Code Pro','SourceCodePro-Regular.ttf',400)]:
        css+=f'@font-face{{font-family:"{family}";src:url("fonts/{file}") format("truetype");font-weight:{weight};font-style:normal;font-display:swap}}\n'
    css+=':root{--font-sans:"Anthropic Sans","Source Sans 3",-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;--font-serif:"Anthropic Serif","Source Serif 4",Georgia,"Songti SC",serif;--font-mono:"Source Code Pro",monospace;'
    for k,v in data['metrics'].items():css+='--'+''.join('-'+c.lower() if c.isupper() else c for c in k).lstrip('-')+':'+str(v)+('ms' if k.endswith('Ms') else 'px')+';'
    for role,key in {'Window':'background','PrimaryText':'text','MutedText':'muted','Control':'control','Border':'border','Accent':'accent'}.items():css+='--'+key+':'+data['themes']['dark'][role]+';'
    for role,value in data['components']['dark'].items():css+='--'+role.lower()+':'+value+';'
    css+='}\n';result['src/Meili.Shared/WebCharts/design-tokens.css']=css
    return result

def main():
    check='--check' in sys.argv;bad=[]
    for file,content in outputs().items():
        p=ROOT/file
        if check:
            if not p.exists() or p.read_text()!=content:bad.append(file)
        else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
    if bad:raise SystemExit('Regenerate design system: '+', '.join(bad))
if __name__=='__main__':main()
